<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\Holder\SmtpOutboundConfigPasswordAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the SmtpOutboundConfigPasswordAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class SmtpOutboundConfigPasswordAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getPassword returns null on a freshly created holder.
     */
    public function testPasswordNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigPasswordAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isPasswordAssigned());
        $this->assertNull($holder->getPassword());
    }
}
class ImplWithSmtpOutboundConfigPasswordAttributeHolderUnitTest
{
    use SmtpOutboundConfigPasswordAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedPasswordRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultPassword();
    }
}
